"""Synthetic physical differential-drive world; no recorded pose inputs."""
import math

def inertial(mass,ixx,iyy,izz):
 return f'<inertial><mass>{mass}</mass><inertia><ixx>{ixx}</ixx><iyy>{iyy}</iyy><izz>{izz}</izz><ixy>0</ixy><ixz>0</ixz><iyz>0</iyz></inertia></inertial>'

def build_live_world(states,step_s=.005,real_time_factor=1.,limits=None):
 limits=limits or dict(max_forward_speed_mps=.3,max_reverse_speed_mps=.15)
 forward=float(limits["max_forward_speed_mps"]);reverse=float(limits["max_reverse_speed_mps"])
 if not all(math.isfinite(v) and v>0 for v in [forward,reverse]):raise ValueError("Invalid physical linear speed limits.")
 colors=['0.2 0.7 1 1','1 .65 .15 1','.7 .3 1 1'];models=[]
 for i,state in enumerate(states):
  color=colors[i];name=f'robot_{i}'
  body=f'<link name="base_link"><pose>0 0 .18 0 0 0</pose>{inertial(4,.06,.06,.10)}<collision name="body"><geometry><cylinder><radius>.23</radius><length>.16</length></cylinder></geometry></collision><visual name="body"><geometry><cylinder><radius>.23</radius><length>.16</length></cylinder></geometry><material><ambient>{color}</ambient><diffuse>{color}</diffuse></material></visual><visual name="heading"><pose>.18 0 .1 0 0 0</pose><geometry><box><size>.22 .045 .025</size></box></geometry><material><ambient>1 1 1 1</ambient><diffuse>1 1 1 1</diffuse></material></visual></link>'
  wheels=[]
  for side,y in [('left',.22),('right',-.22)]:
   wheels.append(f'<link name="{side}_wheel"><pose>0 {y} .08 {-math.pi/2} 0 0</pose>{inertial(.2,.00034,.00034,.00064)}<collision name="tire"><geometry><cylinder><radius>.08</radius><length>.05</length></cylinder></geometry><surface><friction><ode><mu>1</mu><mu2>1</mu2></ode></friction></surface></collision><visual name="tire"><geometry><cylinder><radius>.08</radius><length>.05</length></cylinder></geometry><material><ambient>.08 .08 .08 1</ambient><diffuse>.08 .08 .08 1</diffuse></material></visual></link><joint name="{side}_wheel_joint" type="revolute"><parent>base_link</parent><child>{side}_wheel</child><axis><xyz expressed_in="__model__">0 1 0</xyz><limit><lower>-1e16</lower><upper>1e16</upper><effort>20</effort><velocity>30</velocity></limit></axis></joint>')
  castors=[]
  for j,x in enumerate([-.18,.18]):
   castors.append(f'<link name="caster_{j}"><pose>{x} 0 .03 0 0 0</pose>{inertial(.05,.00002,.00002,.00002)}<collision name="ball"><geometry><sphere><radius>.03</radius></sphere></geometry><surface><friction><ode><mu>.001</mu><mu2>.001</mu2></ode></friction></surface></collision><visual name="ball"><geometry><sphere><radius>.03</radius></sphere></geometry></visual></link><joint name="caster_{j}_fixed" type="fixed"><parent>base_link</parent><child>caster_{j}</child></joint>')
  plugins=f'<plugin filename="gz-sim-diff-drive-system" name="gz::sim::systems::DiffDrive"><left_joint>left_wheel_joint</left_joint><right_joint>right_wheel_joint</right_joint><wheel_separation>.44</wheel_separation><wheel_radius>.08</wheel_radius><topic>/model/{name}/cmd_vel</topic><odom_topic>/model/{name}/wheel_odometry</odom_topic><max_linear_velocity>{forward}</max_linear_velocity><min_linear_velocity>{-reverse}</min_linear_velocity><max_angular_velocity>.8</max_angular_velocity><min_angular_velocity>-.8</min_angular_velocity><max_linear_acceleration>.3</max_linear_acceleration><min_linear_acceleration>-.3</min_linear_acceleration><max_angular_acceleration>.8</max_angular_acceleration><min_angular_acceleration>-.8</min_angular_acceleration></plugin><plugin filename="gz-sim-odometry-publisher-system" name="gz::sim::systems::OdometryPublisher"><odom_frame>world</odom_frame><robot_base_frame>{name}/base_link</robot_base_frame><odom_topic>/model/{name}/odometry</odom_topic><odom_publish_frequency>200</odom_publish_frequency><dimensions>2</dimensions></plugin>'
  models.append(f'<model name="{name}" canonical_link="base_link"><pose>{state["x"]} {state["y"]} 0 0 0 {state["heading"]}</pose>{body}{"".join(wheels)}{"".join(castors)}{plugins}</model>')
 return f'<?xml version="1.0"?><sdf version="1.9"><world name="swarm_live"><physics name="live" type="ignored"><max_step_size>{step_s}</max_step_size><real_time_factor>{real_time_factor}</real_time_factor></physics><plugin filename="gz-sim-physics-system" name="gz::sim::systems::Physics"/><plugin filename="gz-sim-user-commands-system" name="gz::sim::systems::UserCommands"/><plugin filename="gz-sim-scene-broadcaster-system" name="gz::sim::systems::SceneBroadcaster"/><scene><ambient>.6 .6 .6 1</ambient><background>.15 .2 .25 1</background><grid>true</grid><shadows>false</shadows></scene><light name="sun" type="directional"><pose>0 0 10 0 0 0</pose><diffuse>.9 .9 .9 1</diffuse><direction>-.3 -.2 -1</direction></light><model name="ground"><static>true</static><link name="ground"><collision name="floor"><geometry><plane><normal>0 0 1</normal><size>30 30</size></plane></geometry></collision><visual name="floor"><geometry><plane><normal>0 0 1</normal><size>30 30</size></plane></geometry><material><ambient>.35 .4 .4 1</ambient><diffuse>.35 .4 .4 1</diffuse></material></visual></link></model>{"".join(models)}</world></sdf>'
